"""Independent source objects, native vertices untouched; transforms only, no ICP."""
from hero_evaluate import *
import matplotlib
matplotlib.use('Agg')
from matplotlib import colormaps

def camera_mesh(C,K):
 pixels=np.array([[0,0],[639,0],[639,359],[0,359]]);corners=(np.c_[pixels,np.ones(4)]@np.linalg.inv(K).T*2)@C[:3,:3].T+C[:3,3];V=np.r_[C[:3,3][None],corners];F=np.array([[0,1,2],[0,2,3],[0,3,4],[0,4,1]]);return trimesh.Trimesh(V,F,process=False)

def main():
 checkfreeze('provenance/ALL_FINAL_CAMERA_CANDIDATES_FROZEN_BEFORE_HERO.json');r=getresults();views=load(N/'config/VIEWS.json');entries=[];out=N/'local_results/interactive';out.mkdir(exist_ok=True)
 for g in GROUPS:
  conf,data0=sources(g,r,'B0');ring=np.load(conf['ring']['path']);scene0=trimesh.Scene(base_frame='RingWorld');layers=[]
  rm=trimesh.Trimesh(ring['V'],ring['F'],process=False);rm.visual.vertex_colors=np.tile([8,8,8,255],(len(ring['V']),1));scene0.add_geometry(rm,node_name='Ring_CAD_FIXED',geom_name='Ring_CAD_FIXED');layers.append(dict(node='Ring_CAD_FIXED',kind='Ring',source=conf['ring'],default_visible=True))
  for method in ['B0','B1','B2','B3']:
   if not r[g,method].get('poses'):continue
   _,data=sources(g,r,method)
   for i,s in enumerate(data):
    if'V'not in s:continue
    m=trimesh.Trimesh(s['mesh']['V'],s['F'],process=False);color=np.r_[np.array(colormaps['tab20'](i%20)[:3])*255,255].astype(np.uint8);m.visual.vertex_colors=np.tile(color,(len(m.vertices),1));name=method+'__HERO__'+s['id'];scene0.add_geometry(m,node_name=name,geom_name=name,transform=s['D']);layers.append(dict(node=name,kind='HERO',method=method,source_id=s['id'],video=s['video'],source_mesh=asset(s['source']['mesh']['path']),native_face_ids='original_face_id in source_npz',D_mm=s['D'],C_mm=s['C'],default_visible=method=='B0',note=s['status']))
   for v in [v for v in views if v['group']==g]:
    C=getpose(r,g,method,v['id']);cm=camera_mesh(C,np.array(v['K']));cm.visual.face_colors=np.tile([70,70,70,100],(len(cm.faces),1));name=method+'__CAMERA__'+v['id'];scene0.add_geometry(cm,node_name=name,geom_name=name);layers.append(dict(node=name,kind='CAMERA',method=method,canonical_id=v['id'],C_mm=C,default_visible=False))
  for tag,b in conf['bodies'].items():
   z=np.load(b['path']);F=z['F_solid']if'F_solid'in z else z['F'];bm=trimesh.Trimesh(z['V'],F,process=False);bm.visual.vertex_colors=np.tile([145,145,145,110],(len(bm.vertices),1));name='OPTIONAL_FROZEN_018_'+tag;scene0.add_geometry(bm,node_name=name,geom_name=name);layers.append(dict(node=name,kind='BODY',source=b,default_visible=False,frozen_not_updated=True))
  # glTF specifies meters. One common root unit conversion (not fitted scale)
  # preserves Ring anchored coordinates; 1000*worldGLTF==worldmillimeters.
  scene0.apply_transform(np.diag([.001,.001,.001,1]));scene0.metadata.update(task='TASK-E4-RING-FIRST-UNIFIED-BA-001',gltf_world_unit='meter',research_world_unit='millimeter',world_mm_equals_gltf_world_times=1000,no_ICP=True,no_fusion=True,no_geometry_repair=True)
  path=out/(g+'_CAMERA_HERO_COMPARISON.glb');path.write_bytes(scene0.export(file_type='glb',include_normals=True));reload=trimesh.load(path,force='scene');bounderr=float(np.max(abs(reload.bounds-scene0.bounds)));assert bounderr<1e-6
  nativebounds=np.r_[ring['V'],*[s['V'][np.unique(s['F'])]for s in data0 if'V'in s]];focus=(nativebounds.max(0)+nativebounds.min(0))/2*.001;radius=np.linalg.norm(nativebounds*.001-focus,axis=1).max();manifest=dict(group=g,glb=asset(path),nodes=layers,focus_m=focus,radius_m=float(radius),unit='meters in GLB, multiply1000 for mm',roundtrip_bounds_error_m=bounderr,geometry_nodes=len(scene0.geometry),default_method='B0',no_source_trimming_or_repair=True);save('assets_index/'+g+'_GLB_LAYER_MANIFEST.json',manifest);entries.append(dict(group=g,GLB=asset(path),layer_manifest=str(N/'assets_index'/ (g+'_GLB_LAYER_MANIFEST.json')),node_N=len(layers),roundtrip_bounds_error_m=bounderr))
  html='''<!doctype html><meta charset="utf-8"><title>Native HERO layer viewer</title><style>body{margin:0;background:#eee;font:14px sans-serif}#ui{position:absolute;z-index:2;top:8px;left:8px;background:#fffD;padding:12px;max-height:85vh;overflow:auto;width:300px}canvas{display:block}label{display:block}small{color:#555}</style><div id="ui"><b>GROUP — native HERO, no fusion</b><p>Shared Ring world. Units: mm in research, meters in GLB.<br>Drag to orbit; scroll to zoom. Gray body and cameras optional.</p><select id="method"></select><div id="layers"></div><small>All layers are original triangles plus registered transforms. Sources may conflict. B3: POSE_CHANGED_DEPTH_NOT_REINFERRED.</small></div><script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.169.0/examples/jsm/"}}</script><script type="module">
import * as THREE from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);document.body.appendChild(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color(0xf0f0f0);const camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,.00001,10);camera.up.set(0,0,1);const focus=new THREE.Vector3(...FOCUS);const rad=RADIUS;camera.position.copy(focus).add(new THREE.Vector3(rad*2,-rad*2,rad*1.4));const controls=new OrbitControls(camera,renderer.domElement);controls.target.copy(focus);controls.update();scene.add(new THREE.HemisphereLight(0xffffff,0x777777,2));const lamp=new THREE.DirectionalLight(0xffffff,2);lamp.position.set(1,-2,3);scene.add(lamp);let root;const select=document.getElementById('method');for(const m of ['B0','B1','B2','B3']){const o=document.createElement('option');o.value=m;o.text=m;select.append(o);}const nodes=[];const checks=[];function apply(){for(const [n,cb] of checks){const active=!n.name.includes('__')||n.name.startsWith(select.value+'__');n.visible=active&&cb.checked;}}new GLTFLoader().load('FILE',gltf=>{root=gltf.scene;scene.add(root);root.traverse(n=>{if(!n.isMesh)return;nodes.push(n);const label=document.createElement('label');const cb=document.createElement('input');cb.type='checkbox';cb.checked=n.name.includes('HERO')||n.name.includes('Ring');label.append(cb,document.createTextNode(n.name));document.getElementById('layers').append(label);checks.push([n,cb]);cb.onchange=apply;});apply();});select.onchange=apply;onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);};function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera);}animate();</script>'''
  html=html.replace('GROUP',g).replace('FOCUS',json.dumps(focus.tolist())).replace('RADIUS',repr(float(radius))).replace("'FILE'",json.dumps(path.name));(out/(g+'_VIEWER.html')).write_text(html)
 save('assets_index/INTERACTIVE_GLBS.json',entries);print('ALL4_GLB_EXPORTED',[(r['group'],r['GLB']['bytes'])for r in entries],flush=True)
if __name__=='__main__':main()
